enum class SendState {
    progress,
    would_block,
    interrupted,
    error,
};

struct SendAttempt {
    SendState state;
    std::size_t count;
    int error;
};

enum class SendOutcome {
    complete,
    timed_out,
    cancelled,
    error,
    invalid_result,
    invalid_request,
};

struct SendReport {
    SendOutcome outcome;
    std::size_t accepted;
    int error;
};

template <typename Sender, typename Now, typename Pause, typename Cancelled>
SendReport send_until(const std::uint8_t* data,
                      std::size_t size,
                      std::chrono::steady_clock::time_point deadline,
                      Sender send,
                      Now now,
                      Pause pause,
                      Cancelled cancelled) {
    // Empty transfer: no callbacks, no pointer arithmetic, null data is fine.
    if (size == 0) {
        return SendReport{SendOutcome::complete, 0, 0};
    }
    if (data == nullptr) {
        return SendReport{SendOutcome::invalid_request, 0, 0};
    }

    std::size_t accepted = 0;
    while (accepted < size) {
        if (cancelled()) {
            return SendReport{SendOutcome::cancelled, accepted, 0};
        }

        const std::chrono::steady_clock::time_point current = now();
        if (current >= deadline) {
            return SendReport{SendOutcome::timed_out, accepted, 0};
        }

        const std::size_t remaining = size - accepted;
        const SendAttempt attempt = send(data + accepted, remaining);

        // Validate before trusting count: progress must move 1..remaining with no
        // error; every other state must report count 0.
        if (attempt.state == SendState::progress) {
            if (attempt.count < 1 || attempt.count > remaining || attempt.error != 0) {
                return SendReport{SendOutcome::invalid_result, accepted, 0};
            }
        } else {
            if (attempt.count != 0) {
                return SendReport{SendOutcome::invalid_result, accepted, 0};
            }
            if (attempt.state != SendState::error && attempt.error != 0) {
                return SendReport{SendOutcome::invalid_result, accepted, 0};
            }
        }

        switch (attempt.state) {
            case SendState::progress:
                accepted += attempt.count;
                break;
            case SendState::would_block: {
                // Same clock type as the deadline keeps (std::min) well-typed;
                // the parentheses dodge any min macro.
                const auto cap = std::chrono::duration_cast<std::chrono::steady_clock::duration>(
                    std::chrono::milliseconds(1));
                const auto after = now();
                if (after >= deadline) return {SendOutcome::timed_out, accepted, 0};
                const auto wait = (std::min)(deadline - after, cap);
                pause(wait);
                break;
            }
            case SendState::interrupted:
                // No sleep: the next iteration rechecks deadline and cancellation.
                break;
            case SendState::error:
                return SendReport{SendOutcome::error, accepted, attempt.error};
            default:
                return SendReport{SendOutcome::invalid_result, accepted, 0};
        }
    }

    // All bytes accepted; crossing the deadline after the final attempt is fine.
    return SendReport{SendOutcome::complete, accepted, 0};
}

SendAttempt try_send(Socket& socket, const std::uint8_t* data, std::size_t size) noexcept {
    if (!socket.valid()) {
        return SendAttempt{SendState::error, 0, kInvalidArgument};
    }
    if (data == nullptr || size == 0) {
        return SendAttempt{SendState::error, 0, kInvalidArgument};
    }

#if defined(_WIN32)
    const SOCKET handle = static_cast<SOCKET>(socket.native());
    const int chunk = io_chunk_size(size);
    const int n = ::send(handle, reinterpret_cast<const char*>(data), chunk, 0);
    if (n == SOCKET_ERROR) {
        const int err = ::WSAGetLastError();
        if (err == WSAEWOULDBLOCK) {
            return SendAttempt{SendState::would_block, 0, 0};
        }
        // WSAEINTR is cancellation here, not a retryable interruption.
        return SendAttempt{SendState::error, 0, err};
    }
    if (n > 0) {
        return SendAttempt{SendState::progress, static_cast<std::size_t>(n), 0};
    }
    // A zero-byte send is a synthetic failure; do not read stale error state.
    return SendAttempt{SendState::error, 0, WSAECONNABORTED};
#else
#if defined(__linux__)
    constexpr int kSendFlags = MSG_NOSIGNAL;
#else
    constexpr int kSendFlags = 0;  // macOS: SIGPIPE already suppressed via SO_NOSIGPIPE.
#endif
    const int fd = static_cast<int>(socket.native());
    const int chunk = io_chunk_size(size);
    const ssize_t n = ::send(fd, data, static_cast<std::size_t>(chunk), kSendFlags);
    if (n < 0) {
        const int err = errno;
        if (err == EINTR) {
            return SendAttempt{SendState::interrupted, 0, 0};
        }
        if (err == EAGAIN || err == EWOULDBLOCK) {
            return SendAttempt{SendState::would_block, 0, 0};
        }
        return SendAttempt{SendState::error, 0, err};
    }
    if (n > 0) {
        return SendAttempt{SendState::progress, static_cast<std::size_t>(n), 0};
    }
    return SendAttempt{SendState::error, 0, EIO};
#endif
}

SendReport send_bounded(Socket& socket,
                        const std::uint8_t* data,
                        std::size_t size,
                        std::chrono::steady_clock::time_point deadline,
                        const std::atomic_bool* cancel) {
    // Requires a nonblocking socket; the mode is not changed here.
    const auto sender = [&socket](const std::uint8_t* bytes, std::size_t count) {
        return try_send(socket, bytes, count);
    };
    const auto now = []() { return std::chrono::steady_clock::now(); };
    const auto pause = [](std::chrono::steady_clock::duration wait) {
        std::this_thread::sleep_for(wait);
    };
    const auto cancelled = [cancel]() {
        return cancel != nullptr && cancel->load(std::memory_order_relaxed);
    };
    return send_until(data, size, deadline, sender, now, pause, cancelled);
}

bool set_nonblocking(Socket& socket, bool enabled, int& error) noexcept {
    if (!socket.valid()) {
        error = kInvalidArgument;
        return false;
    }

#if defined(_WIN32)
    u_long mode = enabled ? 1UL : 0UL;
    if (::ioctlsocket(static_cast<SOCKET>(socket.native()), FIONBIO, &mode) == SOCKET_ERROR) {
        error = ::WSAGetLastError();
        return false;
    }
#else
    const int fd = static_cast<int>(socket.native());
    const int flags = ::fcntl(fd, F_GETFL, 0);
    if (flags < 0) {
        error = errno;
        return false;
    }
    // Preserve unrelated flags; only toggle O_NONBLOCK.
    const int updated = enabled ? (flags | O_NONBLOCK) : (flags & ~O_NONBLOCK);
    if (::fcntl(fd, F_SETFL, updated) < 0) {
        // Capture immediately; a failed fcntl is not retried on EINTR.
        error = errno;
        return false;
    }
#endif

    error = 0;
    return true;
}

